def mmr(
    query: dict[str, float],
    candidates: dict[str, dict[str, float]],
    k: int,
    lambda_: float = 0.7,
) -> list[tuple[str, float]]:
    """Maximal Marginal Relevance selection.

    Plain top-k returns k articles that are all near-copies of each other, which
    wastes most of the context budget restating one thing. MMR trades a little
    relevance for coverage: each pick is scored on similarity to the query minus
    its similarity to what has already been picked. Same token spend, more of
    the corpus actually represented - which is where non-obvious links come from.
    """
    if k <= 0 or not candidates:
        return []
    relevance = {name: cosine(query, vec) for name, vec in candidates.items()}
    selected: list[tuple[str, float]] = []
    remaining = set(candidates)

    while remaining and len(selected) < k:
        best_name, best_score = None, -1e9
        for name in remaining:
            redundancy = max(
                (cosine(candidates[name], candidates[s]) for s, _ in selected),
                default=0.0,
            )
            score = lambda_ * relevance[name] - (1.0 - lambda_) * redundancy
            if score > best_score:
                best_name, best_score = name, score
        if best_name is None:
            break
        selected.append((best_name, relevance[best_name]))
        remaining.discard(best_name)
    return selected
